<script>
(()=>{const root=document.querySelector('#ol-demo');if(!root)return;const stage=root.querySelector('.ol-stage'),planet=root.querySelector('.ol-planet'),nodes=[...root.querySelectorAll('.ol-node')],info=root.querySelector('.ol-selected'),line=root.querySelector('#ol-signal'),point=root.querySelector('#ol-point');let selected=0,raf=0;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;function sync(){const rect=stage.getBoundingClientRect(),c=planet.getBoundingClientRect(),n=nodes[selected].getBoundingClientRect();const x1=c.left+c.width/2-rect.left,y1=c.top+c.height/2-rect.top,x2=n.left+n.width/2-rect.left,y2=n.top+n.height/2-rect.top;for(const [k,v] of Object.entries({x1,y1,x2,y2}))line.setAttribute(k,v);point.setAttribute('cx',x2);point.setAttribute('cy',y2)}function choose(i){selected=i;nodes.forEach((n,j)=>{n.classList.toggle('active',i===j);n.setAttribute('aria-pressed',String(i===j))});info.querySelector('span').textContent=String(i+1).padStart(2,'0')+' / '+nodes[i].dataset.title;info.querySelector('strong').textContent=nodes[i].dataset.desc;sync()}nodes.forEach((n,i)=>{n.addEventListener('click',()=>{if(selected===i)window.location.href=n.dataset.link;else choose(i)});n.addEventListener('mouseenter',()=>choose(i));n.addEventListener('focus',()=>choose(i))});if(!reduced&&window.matchMedia('(pointer:fine)').matches){stage.addEventListener('pointermove',e=>{const r=stage.getBoundingClientRect();stage.style.setProperty('--px',((e.clientX-r.left-r.width/2)/r.width*25).toFixed(1)+'px');stage.style.setProperty('--py',((e.clientY-r.top-r.height/2)/r.height*25).toFixed(1)+'px');if(!raf)raf=requestAnimationFrame(()=>{sync();raf=0})},{passive:true});stage.addEventListener('pointerleave',()=>{stage.style.setProperty('--px','0px');stage.style.setProperty('--py','0px');requestAnimationFrame(sync)})}window.addEventListener('resize',sync,{passive:true});window.addEventListener('load',sync,{once:true});if('ResizeObserver'in window)new ResizeObserver(sync).observe(stage);requestAnimationFrame(sync)})();
</script>
